#!/usr/bin/env python3
"""Test what happens when pdftk is not available but qpdf is"""

import subprocess
import sys
import os

# Add the current directory to Python path
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from paper2remarkable.utils import check_pdftool
from paper2remarkable.exceptions import NoPDFToolError

def test_tool_detection_when_pdftk_missing():
    """Test tool detection when pdftk is not available"""
    print("Testing tool detection when pdftk is not available...")

    # Test with non-existent pdftk path but valid qpdf
    try:
        result = check_pdftool("/nonexistent/pdftk", "qpdf")
        print(f"Result with nonexistent pdftk: {result}")
    except NoPDFToolError as e:
        print(f"NoPDFToolError: {e}")
    except Exception as e:
        print(f"Other error: {e}")

    # Test with pdftk that returns error
    try:
        result = check_pdftool("false", "qpdf")  # false command always fails
        print(f"Result with false pdftk: {result}")
    except NoPDFToolError as e:
        print(f"NoPDFToolError with false: {e}")
    except Exception as e:
        print(f"Other error with false: {e}")

def test_current_behavior():
    """Test the current behavior"""
    print("\nTesting current behavior with real tools...")
    try:
        result = check_pdftool("pdftk", "qpdf")
        print(f"Available tool: {result}")
    except NoPDFToolError as e:
        print(f"NoPDFToolError: {e}")
    except Exception as e:
        print(f"Other error: {e}")

if __name__ == "__main__":
    test_current_behavior()
    test_tool_detection_when_pdftk_missing()

