sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

def test_utils_module():
    """Test that we can import and use the utils module"""
    try:
        from paper2remarkable.utils import check_pdftool
        from paper2remarkable.exceptions import NoPDFToolError

        print("✓ Successfully imported utils module")

        # Test the fixed function
        print("Testing check_pdftool function...")

