#!/usr/bin/env python3
"""Test integration with provider base class"""

import sys
import os

# Add the current directory to Python path
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

def test_provider_integration():
    """Test that providers can initialize correctly with our fix"""
    try:
        from paper2remarkable.providers._base import Provider
        from paper2remarkable.exceptions import NoPDFToolError

        print("✓ Successfully imported provider base class")

        # Create a minimal provider subclass for testing
        class TestProvider(Provider):
            @staticmethod
            def validate(src):
                return True

            def get_abs_pdf_urls(self, src):
                return "", ""

        print("Testing provider initialization...")

        # Test case 1: Normal initialization (both tools available)
        try:
            provider = TestProvider(
                pdftk_path="pdftk",
                qpdf_path="qpdf",
                upload=False,
                verbose=False
            )
            print(f"✓ Normal init test: pdftool = {provider.pdftool}")
            assert provider.pdftool == "pdftk", f"Expected pdftk, got {provider.pdftool}"
        except Exception as e:
            print(f"✗ Normal init test failed: {e}")

        # Test case 2: pdftk missing, qpdf available (the main issue we're fixing)
        try:
            provider = TestProvider(
                pdftk_path="/nonexistent/pdftk",  # Simulate missing pdftk
                qpdf_path="qpdf",
                upload=False,
                verbose=False
            )
            print(f"✓ Missing pdftk init test: pdftool = {provider.pdftool}")
            assert provider.pdftool == "qpdf", f"Expected qpdf, got {provider.pdftool}"
        except Exception as e:
            print(f"✗ Missing pdftk init test failed: {e}")

        # Test case 3: Neither tool available
        try:
            provider = TestProvider(
                pdftk_path="/nonexistent/pdftk",
                qpdf_path="/nonexistent/qpdf",
                upload=False,
                verbose=False
            )
            print(f"✗ Should have failed but got: pdftool = {provider.pdftool}")
        except NoPDFToolError:
            print("✓ No tools init test: correctly raised NoPDFToolError")
        except Exception as e:
            print(f"✗ No tools init test failed unexpectedly: {e}")

        print("All provider integration tests completed!")

    except ImportError as e:
        print(f"✗ Failed to import provider: {e}")
    except Exception as e:
        print(f"✗ Unexpected error: {e}")

if __name__ == "__main__":
    test_provider_integration()
